function docsFor(id){return (state.documents||[]).filter(d=>d.employeeId===id&&d.active!==false);}
function documentSection(id){const docs=docsFor(id),required=state.settings.requiredDocuments||[],approved=docs.filter(d=>d.status==='approved').length;return '<div style="margin-top:20px">'+card(lawText('مسوغات التعيين','Employment documents'),lawText('أرشيف مستندات خاص لكل موظف داخل Google Drive','Private per-employee document archive in Google Drive'),'<div class="toolbar"><span class="badge '+(approved===required.length?'green':'amber')+'">'+approved+'/'+required.length+' '+lawText('مستند معتمد','approved documents')+'</span><span class="badge">'+(LIVE?'Google Drive':lawText('تخزين تجريبي داخل المتصفح','Demo browser storage'))+'</span></div><div style="margin-top:15px">'+required.map(type=>{const d=docs.find(d=>d.type===type);return '<div class="module"><span class="action-icon">▱</span><div><h3>'+esc(type)+'</h3><p>'+(d?esc(d.name)+' • '+fmt(d.size/1024)+' KB':lawText('لم يرفع بعد','Not uploaded yet'))+'</p>'+(d?badge(d.status)+(d.reason?'<p>'+esc(d.reason)+'</p>':''):'')+'</div><div class="toolbar">'+btn(d?lawText('استبدال','Replace'):lawText('رفع الملف','Upload'),'uploadDoc',id+'|'+type,'small primary')+(d?btn(lawText('عرض / تحميل','View / download'),'downloadDoc',d.id,'small'):'')+(d&&isHR()?btn(lawText('مراجعة','Review'),'reviewDoc',d.id,'small gold'):'')+'</div></div>';}).join('')+'</div><p style="font-size:10px">'+lawText('PDF أو PNG أو JPEG، بحد أقصى 2 MB للملف. المتطلبات سياسة شركة قابلة للتعديل، وليست قائمة قانونية إلزامية.','PDF, PNG or JPEG, up to 2 MB per file. Requirements are an editable company policy, not a statutory checklist.')+'</p>',isHR()?btn(lawText('تعديل المتطلبات','Edit requirements'),'docRequirements','','small'):'')+'</div>';}
let demoDbPromise;
function demoDb(){if(!demoDbPromise)demoDbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open('zarqa-people-docs',1);request.onupgradeneeded=()=>request.result.createObjectStore('files');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});return demoDbPromise;}
async function demoFilePut(id,file){const db=await demoDb();return new Promise((resolve,reject)=>{const t=db.transaction('files','readwrite');t.objectStore('files').put(file,id);t.oncomplete=resolve;t.onerror=()=>reject(t.error);});}
async function demoFileGet(id){const db=await demoDb();return new Promise((resolve,reject)=>{const r=db.transaction('files').objectStore('files').get(id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;try{if(a==='uploadDoc'){const [eid,type]=id.split('|');modal('<h2>'+lawText('رفع مسوغات التعيين','Upload employment document')+'</h2><p>'+esc(type)+' • '+esc(person(eid)?.name)+'</p><form id="documentUpload"><input type="hidden" name="employeeId" value="'+eid+'"><input type="hidden" name="type" value="'+esc(type)+'"><div class="field"><label for="documentFile">'+lawText('اختيار الملف','Choose file')+'</label><input type="file" id="documentFile" accept="application/pdf,image/png,image/jpeg" required></div><div class="field"><label for="uploadExpiry">'+lawText('تاريخ الانتهاء إن وجد','Expiry date, if applicable')+'</label><input id="uploadExpiry" type="date" name="expiresAt"></div><p>'+lawText(LIVE?'سيحفظ في أرشيف Drive الخاص بالشركة، داخل مجلد الموظف.':'في العرض، يحفظ الملف في هذا المتصفح فقط. استخدم ملفات تجريبية.',LIVE?'Stored in the private company Drive archive, inside the employee folder.':'In the demo, files stay in this browser. Use fictional sample documents.')+'</p><div class="form-actions"><button type="submit" class="btn primary">'+lawText('رفع إلى الأرشيف','Upload to archive')+'</button></div></form>');}
if(a==='downloadDoc'){el.disabled=true;let blob,name;const d=state.documents.find(d=>d.id===id);if(LIVE){const r=await callServer('getDocument',{id});const bytes=Uint8Array.from(atob(r.base64),c=>c.charCodeAt(0));blob=new Blob([bytes],{type:r.mime});name=r.name;}else{blob=await demoFileGet(d.blobId);name=d.name;if(!blob)throw Error(lawText('الملف غير موجود في هذا المتصفح. أعد رفعه.','This browser has no file bytes. Please upload it again.'));}downloadBlob(blob,name);el.disabled=false;}
if(a==='reviewDoc'){const d=state.documents.find(d=>d.id===id);form(lawText('مراجعة المستند','Review document')+' • '+esc(d.type),'<input type="hidden" name="id" value="'+d.id+'">'+selectField(lawText('القرار','Decision'),'status',[{value:'approved',label:lawText('قبول','Approve')},{value:'rejected',label:lawText('طلب استبدال','Request replacement')}])+field(lawText('سبب / ملاحظة','Reason / note'),'reason','text',d.reason||lawText('تمت المراجعة','Reviewed')),'documentReview');}
if(a==='docRequirements'){form(lawText('المستندات المطلوبة','Required documents'),'<div class="field"><label>'+lawText('اسم كل مستند في سطر مستقل','One document name per line')+'</label><textarea name="requirements" required>'+esc(state.settings.requiredDocuments.join('\n'))+'</textarea></div>','requirements');}
}catch(err){toast(err.message||String(err));el.disabled=false;}});
document.addEventListener('submit',async e=>{if(e.target.id!=='documentUpload')return;e.preventDefault();if(busy)return;const fd=new FormData(e.target),file=$('documentFile').files[0];if(!file||file.size>2097152||!['application/pdf','image/png','image/jpeg'].includes(file.type))return toast(lawText('اختر PDF أو PNG أو JPEG أقل من 2 MB.','Choose a PDF, PNG or JPEG under 2 MB.'));busy=true;try{const payload={employeeId:fd.get('employeeId'),type:fd.get('type'),name:file.name,mime:file.type,size:file.size,expiresAt:fd.get('expiresAt')||''};if(LIVE){payload.base64=await new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.readAsDataURL(file);});state=await callServer('uploadDocument',payload);}else{payload.blobId='DOC-'+Date.now();await demoFilePut(payload.blobId,file);hrMutate(state,'document.register',payload,{role,email:actorEmail,employeeId,demo:true});}closeModal();render();toast(lawText('تم رفع المستند. ينتظر مراجعة HR.','Document uploaded. Awaiting HR review.'));}catch(err){toast(err.message||String(err));}finally{busy=false;}});
